on conflict(id) do update set name=excluded.name,url=excluded.url,publisher=excluded.publisher,accessed_on=current_date;

on conflict(id) do update set crop=excluded.crop,name=excluded.name,condition_type=excluded.condition_type,affected_parts=excluded.affected_parts,symptoms=excluded.symptoms,confirmation=excluded.confirmation,actions=excluded.actions,source_id=excluded.source_id,updated_at=now();
